import { ApiError, NetworkError, TimeoutError, isOffline } from './errors';
import { isRegisteredErrorCode, ERROR_MESSAGES } from '../i18n/errors';
import { LocalStorageTokenStore, type TokenStore } from './tokenStore';
import type { MediaItem, PosterCandidatesResponse } from '../types/media-item';
import type { MusicArtist, MusicAlbum, MusicTrack } from '../types/music';

/** Re-exported so `import { ApiError } from '.../api/client'` deep imports keep working. */
export { ApiError } from './errors';

/** Re-exported so `import type { TokenStore } from '.../api/client'` deep imports keep working. */
export type { TokenStore } from './tokenStore';

/**
 * Default token store: persist + read the session token from `localStorage` in
 * the browser, and a no-op when there is no `window` (SSR / unit construction).
 *
 * Historically the default was a pure no-op, so any `ApiClient` created WITHOUT
 * an explicit `tokenStore` (the exported {@link api} singleton, the media store,
 * the hub's My-Servers / Federation pages, …) silently sent NO `Authorization`
 * header — which read as "unauthorized" against an authed endpoint and left the
 * media listing readable without a token. Defaulting to the real store makes
 * every client send the logged-in user's Bearer token unless one is overridden.
 */
function defaultTokenStore(): TokenStore {
    if (typeof window === 'undefined') {
        return {
            getAccessToken: () => null,
            setAccessToken: () => {},
            getRefreshToken: () => null,
            setRefreshToken: () => {},
            getUser: () => null,
            setUser: () => {},
            clear: () => {},
        };
    }
    return new LocalStorageTokenStore();
}

/** Default per-request timeout (ms) before the client aborts with a `TimeoutError`. */
const DEFAULT_TIMEOUT_MS = 15000;

export interface AuthUser {
    id: string;
    email?: string;
    username?: string;
    name?: string;
    is_admin?: boolean;
    avatar_url?: string | null;
    [key: string]: unknown;
}

export interface ApiClientOptions {
    baseUrl?: string;
    tokenStore?: TokenStore;
    fetchImpl?: typeof fetch;
    /** Per-request timeout in ms before aborting with a `TimeoutError` (default 15000). */
    timeoutMs?: number;
    /** Extra headers merged into every request from THIS instance (e.g. native-device
     *  identity headers). `Content-Type`/`Authorization` always win; a falsy/empty
     *  value is omitted rather than sent as an empty header. */
    headers?: Record<string, string>;
    /**
     * Path (relative or absolute) the {@link ApiClient.logout} redirect target is
     * prepended with. Defaults to `'/login'`. On the hub where the SPA lives under
     * `/app` this would be set to `'/app/login'` so a logout redirect does not 404.
     */
    loginPath?: string;
}

/**
 * Headers merged into EVERY {@link ApiClient} request, set once at app boot
 * (e.g. the native-client device headers `X-Phlix-Device-*` / `X-Phlix-Session-ID`).
 * Module-level so the ~30 `new ApiClient(...)` call sites need no change — every
 * client constructed AFTER {@link setDefaultApiHeaders} picks these up. Falsy/empty
 * values are dropped on set so a not-yet-known header (e.g. an empty session id)
 * never emits a broken empty header.
 */
let defaultHeaders: Record<string, string> = {};

/** Drop falsy/empty-string header values so they never emit a broken empty header. */
function pruneHeaders(headers: Record<string, string>): Record<string, string> {
    const out: Record<string, string> = {};
    for (const [key, value] of Object.entries(headers)) {
        if (value) {
            out[key] = value;
        }
    }
    return out;
}

/**
 * Set the headers merged into EVERY `ApiClient` request (e.g. native-device
 * identity). Replaces any previously-set defaults. Falsy/empty values are
 * dropped. Call once early at app boot, before any client is constructed.
 */
export function setDefaultApiHeaders(headers: Record<string, string>): void {
    defaultHeaders = pruneHeaders(headers);
}

/** The current default headers (a copy; mainly for tests/debug). */
export function getDefaultApiHeaders(): Record<string, string> {
    return { ...defaultHeaders };
}

export function normalizeBool(value: unknown): boolean {
    return value === true || value === 1 || value === '1' || value === 'true';
}

/** Narrow an unknown to a trimmed string (numbers stringify), else null. */
function musicStr(value: unknown): string | null {
    if (typeof value === 'string') {
        return value;
    }
    if (typeof value === 'number' && !Number.isNaN(value)) {
        return String(value);
    }
    return null;
}

/** Narrow an unknown to a finite number (numeric strings parse), else null. */
function musicNum(value: unknown): number | null {
    if (typeof value === 'number' && !Number.isNaN(value)) {
        return value;
    }
    if (typeof value === 'string' && value.trim() !== '' && !Number.isNaN(Number(value))) {
        return Number(value);
    }
    return null;
}

/**
 * Normalize one raw artist row from `GET /api/v1/music/artists` (snake_case,
 * grouped by artist name — the server has no artist PK, so the display `name`
 * doubles as the drill-down key/`mbid`) into the camelCase {@link MusicArtist}.
 */
function normalizeMusicArtist(raw: unknown): MusicArtist {
    const r = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
    const name = musicStr(r['name']) ?? 'Unknown Artist';
    const albumCount = musicNum(r['album_count']);
    // `track_count` is emitted by BOTH the list and detail shapes (`formatArtist()`)
    // and is the artist's TRUE indexed track total. Dropping it forced the artist
    // page to sum the tracks of whichever album page happened to be loaded, which
    // both contradicted the DB and changed as the user paged.
    const trackCount = musicNum(r['track_count']);
    return {
        id: name,
        name,
        imageUrl: musicStr(r['image_url']),
        albumCount: albumCount ?? undefined,
        trackCount: trackCount ?? undefined,
    };
}

/**
 * Normalize one raw track — accepts either the flat formatted shape from
 * `GET /api/v1/music/tracks` (`{ id, name, duration_secs, track_number }`) or a
 * raw scanner item embedded in an album (`{ id, metadata: { title, ... } }`).
 * Track ids are server UUID strings.
 */
function normalizeMusicTrack(raw: unknown): MusicTrack {
    const r = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
    const meta = (r['metadata'] && typeof r['metadata'] === 'object'
        ? r['metadata']
        : {}) as Record<string, unknown>;
    const title = musicStr(meta['title']) ?? musicStr(r['name']) ?? musicStr(r['title']) ?? 'Unknown Track';
    return {
        id: musicStr(r['id']) ?? '',
        title,
        durationSecs: musicNum(meta['duration_secs']) ?? musicNum(r['duration_secs']) ?? 0,
        trackNumber: musicNum(meta['track_number']) ?? musicNum(r['track_number']),
        // Signed direct-play URL from `formatTrack` (/tracks[/{id}]). Raw items
        // embedded in an album carry no `stream_url`, so this stays null there —
        // useMusicPlayer resolves it lazily via getTrack at play time.
        streamUrl: musicStr(r['stream_url']),
    };
}

/**
 * Normalize one raw album row from `GET /api/v1/music/albums` (snake_case,
 * grouped by album name with embedded raw track items) into the camelCase
 * {@link MusicAlbum}. The server groups by album `name` (no album PK), so `name`
 * doubles as the drill-down key/`mbid`; embedded `tracks` are normalized so the
 * album carries a ready track list (browse fast-path — no separate track fetch).
 */
function normalizeMusicAlbum(raw: unknown): MusicAlbum {
    const r = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
    const title = musicStr(r['name']) ?? musicStr(r['title']) ?? 'Unknown Album';
    const rawTracks = Array.isArray(r['tracks']) ? r['tracks'] : [];
    const totalTracks = musicNum(r['track_count']) ?? rawTracks.length;
    return {
        id: title,
        title,
        artist: musicStr(r['artist']),
        albumArtUrl: musicStr(r['album_art_url']),
        year: musicNum(r['year']),
        totalTracks,
        tracks: rawTracks.map(normalizeMusicTrack),
        // S99 caps the tracks embedded in a LIST row (100 per album, and 2,000 per
        // page shared round-robin) and sets `tracks_truncated` for every album whose
        // embedded count is below its true `track_count`. So this flag — not
        // `tracks.length` — decides whether the embedded list may be played as-is
        // or the album detail route has to be fetched for the whole thing.
        tracksTruncated: normalizeBool(r['tracks_truncated']),
    };
}

/**
 * The page size this client asks for on every music listing, and the largest the
 * server will honour: `PageLimit::MAX` on `phlix-server`
 * (`MusicController::listArtists/listAlbums/listTracks` clamp `?limit=` to it).
 *
 * ⚠ Raising this is NOT how you reach the rest of the library — page instead. The
 * server embeds each album's tracks in its list row and mints ONE HMAC-signed
 * `stream_url` per embedded track on the event loop, so a whole-library album page
 * would carry 29,245 embedded tracks (S99 HIGH-1 at full scale). `offset` is the
 * cheap axis: an artist-filtered album page measured 0.95 ms on production against
 * 134 ms unfiltered.
 */
export const MUSIC_PAGE_SIZE = 100;

/** `?limit=`/`?offset=` accepted by every music listing endpoint. */
export interface MusicPageParams {
    limit?: number;
    offset?: number;
}

/**
 * One page of `GET /api/v1/music/artists`. `total` is the server's
 * `SELECT COUNT(*)` over `music_artists` — the TRUE library size, independent of
 * how many rows this page carries — so a UI can both size a pager and show the
 * real count. `limit`/`offset` are the values the server actually APPLIED (it
 * clamps), not the ones requested.
 *
 * Named `…Result`, not `…Page`, for two reasons: it matches the existing
 * {@link FavoritesResult} (the same shape from the same client), and `…Page` would
 * collide with the `MusicArtistsPage` / `MusicTracksPage` *components* the package
 * index already exports — those are public API, so the new types yield the name.
 */
export interface MusicArtistsResult {
    artists: MusicArtist[];
    total: number;
    limit: number;
    offset: number;
}

/**
 * One page of `GET /api/v1/music/albums`. `artist` echoes the server-applied
 * `?artist=` filter (`null` when unfiltered), which is how a client can tell a
 * filtering server from one that silently ignored the parameter; `total` honours
 * the filter.
 */
export interface MusicAlbumsResult {
    albums: MusicAlbum[];
    total: number;
    limit: number;
    offset: number;
    artist: string | null;
}

/** One page of `GET /api/v1/music/tracks`. `total` is the whole-library count. */
export interface MusicTracksResult {
    tracks: MusicTrack[];
    total: number;
    limit: number;
    offset: number;
}

/**
 * Shared page-envelope reader for the three music listings: defends the row array
 * and echoes back the effective `limit`/`offset`/`total`. A server that omits
 * `total` (pre-S99) degrades to "this page is everything", which is what the
 * pre-paging UI assumed anyway.
 */
function musicPageMeta(
    res: { total?: unknown; limit?: unknown; offset?: unknown },
    rows: number,
    requested: MusicPageParams,
): { total: number; limit: number; offset: number } {
    return {
        total: musicNum(res.total) ?? rows,
        limit: musicNum(res.limit) ?? requested.limit ?? MUSIC_PAGE_SIZE,
        offset: musicNum(res.offset) ?? requested.offset ?? 0,
    };
}

/** Build the `?limit=&offset=` query for a music listing, omitting unset values. */
function musicPageQuery(params: MusicPageParams): Record<string, string> {
    const query: Record<string, string> = {};
    if (params.limit !== undefined) query['limit'] = String(params.limit);
    if (params.offset !== undefined) query['offset'] = String(params.offset);
    return query;
}

/** TMDB match type — series/season/episode resolve as `tv`, everything else `movie`. */
export type MatchType = 'tv' | 'movie';

/**
 * One TMDB search candidate as shaped by the server's interactive match API
 * (S5: `GET /api/v1/media/{id}/match/search`). The server caps the list at 20
 * and drops entries with no usable `tmdb_id`. `year` is parsed from the TMDB
 * release/first-air date (null when absent); the image URLs are absolute (w500)
 * or null. Exported from the package index so consumers can type the candidate.
 */
export interface MatchCandidate {
    tmdb_id: number | string;
    type: MatchType;
    title: string;
    year: number | null;
    overview: string | null;
    poster_url: string | null;
    backdrop_url: string | null;
    vote_average?: number;
    [key: string]: unknown;
}

/** Context block attached to each match candidate when the server has metadata. */
export interface MatchContext {
    original_filename?: string | null;
    path?: string | null;
    parsed_title?: string | null;
    year?: number | null;
    tags?: Record<string, unknown>;
}

/** Envelope returned by {@link ApiClient.matchSearch}. */
export interface MatchSearchResult {
    results: MatchCandidate[];
    /** The effective query the server searched (the resolved/echoed term). */
    query: string;
    /** The effective TMDB type the server searched. */
    type: MatchType;
    context?: MatchContext;
}

/** Optional manual overrides for {@link ApiClient.matchSearch}. */
export interface MatchSearchParams {
    /** Search term; the server derives it from the item's title when omitted. */
    query?: string;
    /** Release/first-air year filter; derived from the item when omitted. */
    year?: number | string;
    /** Force `tv`/`movie`; the server derives it from the item type when omitted. */
    type?: MatchType;
}

/** Body for {@link ApiClient.matchApply}. */
export interface MatchApplyInput {
    tmdb_id: number | string;
    type?: MatchType;
}

/** Envelope returned by {@link ApiClient.matchApply} — the re-shaped item + a summary. */
export interface MatchApplyResult<TItem = unknown> {
    /** The freshly re-shaped media item (so the UI can refresh the card/detail). */
    item: TItem;
    applied: {
        item_id: string;
        mode: MatchType;
        tmdb_id: number | string;
        matched: boolean;
        children_enriched: number;
        [key: string]: unknown;
    };
}

/**
 * Envelope returned by {@link ApiClient.listFavorites}
 * (`GET /api/v1/users/me/favorites`). Mirrors the server's paginated list shape:
 * fully shaped media items (each carrying its add-only `user_data` block), plus
 * the effective `limit`/`offset` the server applied. `total` is NOT sent by this
 * endpoint (unlike the browse list) so it is intentionally absent here.
 */
export interface FavoritesResult {
    items: MediaItem[];
    limit: number;
    offset: number;
}

/**
 * One playlist as the server's `Collection::toArray()` ships it
 * (R13-01 member playlist surface). Boundary-parsed: unknown/malformed rows
 * are dropped rather than thrown (a fossil row without `id`/`name` cannot be
 * rendered or acted on anyway).
 */
export interface PlaylistSummary {
    id: string;
    name: string;
    /** Owning library; `null` only on rows older than the column's NOT-NULL-ness
     *  was relaxed — treated as "cannot seed a create", never as a filter. */
    library_id: string | null;
    smart_playlist_id: string | null;
    created_at: string | null;
    updated_at: string | null;
    /** Option A ownership (server migration 112): owning user id, or `null`
     *  for pre-migration rows — which stay visible to every member. */
    created_by: string | null;
}

/**
 * A playlist membership row straight off `GET /api/v1/collections/{id}`:
 * RAW hydrated DB columns (id/name/type are what the server's
 * `ItemRepository::findByIds` guarantees), NOT response-shaped `MediaItem`s —
 * see the {@link ApiClient.getPlaylist} truth note.
 */
export interface PlaylistMediaRow {
    id: string;
    name: string;
    type: string;
}

/** `{ collection, items, total }` envelope of one playlist's detail. */
export interface PlaylistDetail {
    collection: PlaylistSummary;
    items: PlaylistMediaRow[];
    total: number;
}

/** Boundary parser: one `Collection::toArray()` row → `[PlaylistSummary]` or `[]`. */
function parsePlaylistRow(value: unknown): [PlaylistSummary] | [] {
    if (typeof value !== 'object' || value === null) return [];
    const row = value as Record<string, unknown>;
    if (typeof row.id !== 'string' || row.id === '') return [];
    return [
        {
            id: row.id,
            name: typeof row.name === 'string' ? row.name : row.id,
            library_id: typeof row.library_id === 'string' && row.library_id !== '' ? row.library_id : null,
            smart_playlist_id: typeof row.smart_playlist_id === 'string' ? row.smart_playlist_id : null,
            created_at: typeof row.created_at === 'string' ? row.created_at : null,
            updated_at: typeof row.updated_at === 'string' ? row.updated_at : null,
            created_by: typeof row.created_by === 'string' ? row.created_by : null,
        },
    ];
}

/** Boundary parser: one raw media-item DB row → `[PlaylistMediaRow]` or `[]`. */
function parsePlaylistMediaRow(value: unknown): [PlaylistMediaRow] | [] {
    if (typeof value !== 'object' || value === null) return [];
    const row = value as Record<string, unknown>;
    if (typeof row.id !== 'string' || row.id === '') return [];
    return [
        {
            id: row.id,
            name: typeof row.name === 'string' ? row.name : row.id,
            type: typeof row.type === 'string' ? row.type : 'movie',
        },
    ];
}

/** The server error `code` returned (422) when no TMDB API key is configured. */
export const TMDB_UNCONFIGURED_CODE = 'metadata.tmdb_unconfigured';

/**
 * True when a thrown error is the server's `422 metadata.tmdb_unconfigured`
 * response (no TMDB key) — lets the UI show a "configure TMDB" message instead
 * of a generic failure. Reads the parsed `code` off the {@link ApiError} body.
 */
export function isTmdbUnconfigured(e: unknown): boolean {
    if (!(e instanceof ApiError) || e.status !== 422) return false;
    const body = e.body;
    return (
        typeof body === 'object' &&
        body !== null &&
        (body as { code?: unknown }).code === TMDB_UNCONFIGURED_CODE
    );
}

/**
 * One subtitle search candidate from
 * `GET /api/v1/media/{id}/subtitles/search` — mirrors the server contract's
 * ranking signals verbatim (camelCase on the wire). `fps` is null when the
 * provider reports no frame-rate.
 */
export interface SubtitleCandidate {
    provider: string;
    language: string;
    /** Provider-scoped id passed back to the download endpoint. */
    downloadId: string;
    releaseName: string;
    format: string;
    /** How the provider matched (e.g. `hash`, `imdb`, `name`). */
    matchedBy: string;
    /** Provider rating (higher is better); 0 when unknown. */
    rating: number;
    /** Provider download count (popularity); 0 when unknown. */
    downloadCount: number;
    hearingImpaired: boolean;
    /** Frame rate the sub is timed for, or null when unreported. */
    fps: number | null;
}

/** Request body for `POST /api/v1/media/{id}/subtitles/download`. */
export interface SubtitleDownloadPayload {
    provider: string;
    downloadId: string;
    language: string;
    format?: string;
    releaseName?: string;
    hearingImpaired?: boolean;
}

/**
 * The downloaded-track envelope from
 * `POST /api/v1/media/{id}/subtitles/download`. The `track` surfaces through the
 * existing player `subtitle_tracks[]` contract (signed WebVTT url), so callers
 * can feed it straight into `parseSubtitleTracks`.
 */
export interface SubtitleDownloadResult {
    track: Record<string, unknown>;
}

/** Coerce one raw search-candidate object into a typed {@link SubtitleCandidate}. */
function normalizeSubtitleCandidate(raw: unknown): SubtitleCandidate {
    const o = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
    const str = (v: unknown): string => (typeof v === 'string' ? v : '');
    const n = (v: unknown): number =>
        typeof v === 'number' && Number.isFinite(v)
            ? v
            : typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v))
              ? Number(v)
              : 0;
    const fpsRaw = o['fps'];
    const fps =
        typeof fpsRaw === 'number' && Number.isFinite(fpsRaw)
            ? fpsRaw
            : typeof fpsRaw === 'string' && fpsRaw.trim() !== '' && Number.isFinite(Number(fpsRaw))
              ? Number(fpsRaw)
              : null;
    return {
        provider: str(o['provider']),
        language: str(o['language'] ?? o['lang']),
        downloadId: str(o['downloadId'] ?? o['download_id']),
        releaseName: str(o['releaseName'] ?? o['release_name']),
        format: str(o['format']),
        matchedBy: str(o['matchedBy'] ?? o['matched_by']),
        rating: n(o['rating']),
        downloadCount: n(o['downloadCount'] ?? o['download_count']),
        hearingImpaired: normalizeBool(o['hearingImpaired'] ?? o['hearing_impaired']),
        fps,
    };
}

/**
 * R12-06 — is this envelope string a MACHINE token rather than display text?
 *
 * The estate's error envelopes disagree about WHERE the human string rides:
 * the contracts-law shape is `{error: <human text>, code: <wire code>}`, but
 * phlix-server's AccountLinkController emits `error: 'missing_identity_id'`
 * style snake_case tokens in the human slot (and SCREAMING_SNAKE appears in
 * legacy lanes), while dotted forms (`auth.required`) are the registry
 * vocabulary. All three shapes share one property no human sentence has: they
 * are bare identifiers — letters/digits/underscores only (plus dots for
 * registry codes) with at least one separator. Spaces, punctuation and
 * camelCase prose therefore never match.
 */
const MACHINE_TOKEN_PATTERN =
    /^(?:[a-z][a-z0-9_]*_[a-z0-9_]*|[A-Z][A-Z0-9_]*_[A-Z0-9_]*|[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)+)$/;

function isMachineToken(value: string): boolean {
    return MACHINE_TOKEN_PATTERN.test(value);
}

/** English-catalog hit for a registered wire code; `null` for anything else.
 *  Callers that know the UI locale re-localize from `ApiError.body.code` —
 *  this layer is locale-agnostic by construction (no config access here). */
function localizeWireCode(code: string | null): string | null {
    if (code !== null && isRegisteredErrorCode(code)) {
        const english = ERROR_MESSAGES.en[code];
        if (typeof english === 'string' && english !== '') return english;
    }
    return null;
}

export class ApiClient {
    private baseUrl: string;
    private readonly tokens: TokenStore;
    private readonly doFetch: typeof fetch;
    private readonly timeoutMs: number;
    private readonly instanceHeaders: Record<string, string>;
    private readonly loginPath: string;
    /**
     * In-flight token refresh, single-flighted per `ApiClient` instance. When an
     * access token expires, every concurrent request gets a 401 and calls
     * {@link refreshToken} at once; without coordination each would POST
     * `/api/v1/auth/refresh` with the same refresh token. The hub rotates
     * refresh tokens one-time-use, so the second+ POST presents an
     * already-consumed token, fails, and spuriously logs the user out
     * mid-session. Memoising the promise (cleared in `.finally()`) makes the N
     * callers await the SAME refresh — exactly one POST, one rotation.
     */
    private refreshPromise: Promise<boolean> | null = null;

    constructor(options: ApiClientOptions = {}) {
        this.baseUrl = options.baseUrl ?? (typeof window !== 'undefined' ? window.location.origin : '');
        this.tokens = options.tokenStore ?? defaultTokenStore();
        this.doFetch = options.fetchImpl ?? globalThis.fetch.bind(globalThis);
        this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
        this.instanceHeaders = pruneHeaders(options.headers ?? {});
        this.loginPath = options.loginPath ?? '/login';
    }

    /**
     * Re-point this client at a different API base after construction. Lets a
     * long-lived client (e.g. the one held by `useAuthStore`) follow a runtime
     * connection change — the native Connect screen sets the base AFTER the store
     * has already created its client, and consumers hold that same instance, so
     * mutating it in place keeps every reference valid rather than swapping it.
     */
    setBaseUrl(baseUrl: string): void {
        this.baseUrl = baseUrl;
    }

    async request<T = unknown>(
        method: string,
        endpoint: string,
        data: unknown = null,
        signal?: AbortSignal,
    ): Promise<T> {
        const build = (effectiveSignal: AbortSignal): RequestInit => {
            // Merge order: module defaults (device headers) < this instance's
            // headers < the fixed Content-Type — so Content-Type/Authorization
            // always win and a consumer header can never clobber them. `defaultHeaders`
            // and `instanceHeaders` are pre-pruned of falsy/empty values.
            const headers: Record<string, string> = {
                ...defaultHeaders,
                ...this.instanceHeaders,
                'Content-Type': 'application/json',
            };
            const token = this.tokens.getAccessToken();
            if (token) {
                headers['Authorization'] = `Bearer ${token}`;
            }
            const init: RequestInit = {
                method,
                headers,
                credentials: 'same-origin',
                signal: effectiveSignal,
            };
            if (data !== null && (method === 'POST' || method === 'PUT' || method === 'PATCH')) {
                init.body = JSON.stringify(data);
            }
            return init;
        };

        // Resolve the request URL against the configured base. Guard against a
        // double-prepend: several media helpers (`buildMediaUrl`) bake the base
        // INTO the endpoint and are then fetched through a client whose `baseUrl`
        // is that same base. When `baseUrl` is '' (same-origin media server) the
        // extra prefix is empty and harmless, but on the hub `baseUrl` is the
        // relay-proxy path (`/api/v1/servers/{id}/proxy`), so prepending it again
        // produced `…/proxy/api/v1/servers/{id}/proxy/api/v1/media` → 404. If the
        // endpoint already starts with the (non-empty) base, treat it as resolved.
        const url =
            this.baseUrl !== '' && endpoint.startsWith(this.baseUrl)
                ? endpoint
                : `${this.baseUrl}${endpoint}`;

        // Drive every request through our own controller so we can enforce a
        // timeout AND honour a caller's abort signal (e.g. a superseded media
        // request). The timeout sets `timedOut` before aborting so we can tell
        // it apart from a caller-initiated cancellation.
        const controller = new AbortController();
        let timedOut = false;
        const timer = setTimeout(() => {
            timedOut = true;
            controller.abort();
        }, this.timeoutMs);
        const onCallerAbort = (): void => controller.abort();
        if (signal) {
            if (signal.aborted) {
                controller.abort();
            } else {
                signal.addEventListener('abort', onCallerAbort, { once: true });
            }
        }

        try {
            let response = await this.doFetch(url, build(controller.signal));

            if (response.status === 401) {
                const refreshed = await this.refreshToken();
                if (refreshed) {
                    response = await this.doFetch(url, build(controller.signal));
                }
            }

            return await this.handleResponse<T>(response);
        } catch (e) {
            if (timedOut) {
                throw new TimeoutError();
            }
            // A caller-initiated cancellation must stay an AbortError so the
            // store's supersede logic still recognises it.
            if (signal?.aborted) {
                throw e;
            }
            if (e instanceof ApiError) {
                throw e;
            }
            // fetch() rejects with a TypeError on a network failure (DNS,
            // connection refused, offline) — surface it as a friendly NetworkError.
            if (e instanceof TypeError || isOffline()) {
                throw new NetworkError();
            }
            throw e;
        } finally {
            clearTimeout(timer);
            if (signal) {
                signal.removeEventListener('abort', onCallerAbort);
            }
        }
    }

    private async handleResponse<T>(response: Response): Promise<T> {
        // Empty-body success responses (204 No Content / 205 Reset Content) have
        // no JSON to parse — calling `response.json()` on them throws. Some
        // endpoints (e.g. certain DELETEs) return 204, so short-circuit here so
        // the caller's success path runs instead of surfacing a bogus parse error.
        if (response.status === 204 || response.status === 205) {
            return undefined as T;
        }
        const contentType = response.headers.get('content-type') ?? '';
        const isJson = contentType.includes('application/json');
        const payload: unknown = isJson
            ? await response.json()
            : await response.text();

        if (!response.ok) {
            const message = this.extractError(payload);
            throw new ApiError(message, response.status, payload);
        }

        return payload as T;
    }

    private extractError(payload: unknown): string {
        if (payload && typeof payload === 'object') {
            const obj = payload as Record<string, unknown>;
            const error = typeof obj['error'] === 'string' && obj['error'] !== '' ? obj['error'] : null;
            const message =
                typeof obj['message'] === 'string' && obj['message'] !== '' ? obj['message'] : null;
            const code = typeof obj['code'] === 'string' ? obj['code'] : null;

            if (error !== null && isMachineToken(error)) {
                // R12-06 split-brain: some controllers (phlix-server
                // AccountLinkController is the named offender — 'missing_identity_id',
                // 'last_sign_in_method') park a MACHINE token in the `error` slot.
                // It is never display-friendly: localize through the errors.ts
                // catalog first (the `code` slot wins, then the token itself),
                // then the human `message`, and only as a last resort the raw
                // token — an honest token beats a silent 'Request failed'.
                const localized =
                    localizeWireCode(code) ?? localizeWireCode(error);
                if (localized !== null) return localized;
                return message ?? error;
            }

            // Both human slots present ⇒ `message` wins: the estate envelope law
            // treats `error` as the debug-flavored half. Single-slot cases keep
            // whichever string the server sent.
            if (message !== null) return message;
            if (error !== null) return error;

            // Token-less envelope carrying only a registered `code` still gets
            // localized before degrading to the generic label.
            const codeOnly = localizeWireCode(code);
            if (codeOnly !== null) return codeOnly;
        }
        return 'Request failed';
    }

    /**
     * The persisted token pair is provably dead — clear it (nothing downstream
     * should re-send dead credentials) and let the app layer sync. Fires once
     * per determinative failure, inside the single-flighted refresh body.
     */
    private expireSession(): void {
        this.tokens.clear();
        if (typeof window !== 'undefined' && typeof CustomEvent !== 'undefined') {
            window.dispatchEvent(new CustomEvent('phlix:auth-expired'));
        }
    }

    /**
     * Refresh the access token, single-flighted per instance. Concurrent callers
     * (e.g. several requests that all hit a 401 at once) share ONE in-flight
     * refresh rather than each POSTing `/api/v1/auth/refresh` — see
     * {@link refreshPromise}. The promise is cleared in `.finally()` so a later
     * expiry starts a fresh refresh. Returns `true` on success / `false` on any
     * failure (no refresh token, non-2xx, network error, missing access_token).
     *
     * M-UI-26 (seceng: failed refresh kept the tokens): a DETERMINED failure —
     * no refresh token to try, a non-2xx answer, or a payload that carries no
     * access_token — means the persisted pair can never authenticate again, so
     * {@link expireSession} clears the store and fires the `phlix:auth-expired`
     * window event the auth store mirrors into its reactive state. A NETWORK
     * error is deliberately NOT determinative: the pair may still be valid
     * server-side, so tokens survive and the next attempt retries.
     */
    async refreshToken(): Promise<boolean> {
        if (this.refreshPromise !== null) {
            return this.refreshPromise;
        }
        this.refreshPromise = (async (): Promise<boolean> => {
            const refreshToken = this.tokens.getRefreshToken();
            if (!refreshToken) {
                this.expireSession();
                return false;
            }
            try {
                const response = await this.doFetch(`${this.baseUrl}/api/v1/auth/refresh`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'same-origin',
                    body: JSON.stringify({ refresh_token: refreshToken }),
                });
                if (!response.ok) {
                    this.expireSession();
                    return false;
                }
                const data = (await response.json()) as {
                    access_token?: string;
                    refresh_token?: string;
                };
                if (typeof data.access_token !== 'string') {
                    this.expireSession();
                    return false;
                }
                this.tokens.setAccessToken(data.access_token);
                if (typeof data.refresh_token === 'string') {
                    this.tokens.setRefreshToken(data.refresh_token);
                }
                return true;
            } catch {
                // Network-level failure is unknown, not rejected — tokens survive
                // (see refreshToken docblock; M-UI-26 asymmetry is deliberate).
                return false;
            }
        })().finally(() => {
            this.refreshPromise = null;
        });
        return this.refreshPromise;
    }

    async get<T = unknown>(endpoint: string, params?: Record<string, string>, signal?: AbortSignal): Promise<T> {
        const query = params ? '?' + new URLSearchParams(params).toString() : '';
        return this.request<T>('GET', endpoint + query, null, signal);
    }

    async post<T = unknown>(endpoint: string, data?: unknown, signal?: AbortSignal): Promise<T> {
        return this.request<T>('POST', endpoint, data ?? null, signal);
    }

    async put<T = unknown>(endpoint: string, data?: unknown): Promise<T> {
        return this.request<T>('PUT', endpoint, data ?? null);
    }

    async patch<T = unknown>(endpoint: string, data?: unknown): Promise<T> {
        return this.request<T>('PATCH', endpoint, data ?? null);
    }

    async delete<T = unknown>(endpoint: string): Promise<T> {
        return this.request<T>('DELETE', endpoint);
    }

    /**
     * Interactive per-item metadata match — search TMDB candidates for one item
     * (S5: `GET /api/v1/media/{id}/match/search`). All params are optional; the
     * server derives the query/year/type from the item itself when omitted. The
     * envelope (`{ results, query, type }`) is returned verbatim, with `results`
     * defended to an array so a malformed payload degrades to empty rather than
     * throwing on `.map`. A `422 metadata.tmdb_unconfigured` surfaces as an
     * `ApiError` the caller can detect with {@link isTmdbUnconfigured}.
     */
    async matchSearch(
        id: string,
        params: MatchSearchParams = {},
        signal?: AbortSignal,
    ): Promise<MatchSearchResult> {
        const query: Record<string, string> = {};
        if (params.query !== undefined && params.query !== '') query['query'] = params.query;
        if (params.year !== undefined && params.year !== '') query['year'] = String(params.year);
        if (params.type !== undefined) query['type'] = params.type;
        const res = await this.get<Partial<MatchSearchResult>>(
            `/api/v1/media/${encodeURIComponent(id)}/match/search`,
            Object.keys(query).length ? query : undefined,
            signal,
        );
        return {
            results: Array.isArray(res.results) ? res.results : [],
            query: typeof res.query === 'string' ? res.query : (params.query ?? ''),
            type: res.type === 'tv' || res.type === 'movie' ? res.type : (params.type ?? 'movie'),
            context: res.context,
        };
    }

    /**
     * Apply a chosen TMDB match to one item (S5:
     * `POST /api/v1/media/{id}/match/apply`). `type` defaults to the
     * item-derived mode server-side. Returns the re-shaped `{ item, applied }`
     * so the caller can refresh the card/detail in place. Non-2xx (400 bad
     * input, 404, 422 unconfigured/no-match, 502 TMDB unreachable) throw the
     * shared `ApiError`.
     */
    matchApply<TItem = unknown>(id: string, input: MatchApplyInput): Promise<MatchApplyResult<TItem>> {
        return this.post<MatchApplyResult<TItem>>(
            `/api/v1/media/${encodeURIComponent(id)}/match/apply`,
            input,
        );
    }

    /**
     * Mark a media item as a favorite for the authenticated user
     * (`POST /api/v1/media/{id}/favorite`). The backend persists the favorite
     * flag and returns a flat `{ message }`, which we surface verbatim. Non-2xx
     * (401 unauth, 404 unknown id) throw the shared {@link ApiError}.
     */
    addFavorite(id: string): Promise<{ message: string }> {
        return this.post<{ message: string }>(`/api/v1/media/${encodeURIComponent(id)}/favorite`);
    }

    /**
     * Remove a media item from the authenticated user's favorites
     * (`DELETE /api/v1/media/{id}/favorite`). Returns the server's flat
     * `{ message }`. Non-2xx (401, 404) throw the shared {@link ApiError}.
     */
     removeFavorite(id: string): Promise<{ message: string }> {
        return this.delete<{ message: string }>(`/api/v1/media/${encodeURIComponent(id)}/favorite`);
    }

    /**
     * Mark a media item as watched for the authenticated user
     * (`POST /api/v1/media/{id}/watched`). The server returns a flat
     * `{ message }`. Non-2xx throw the shared {@link ApiError}.
     */
    markWatched(id: string): Promise<{ message: string }> {
        return this.post<{ message: string }>(`/api/v1/media/${encodeURIComponent(id)}/watched`);
    }

    /**
     * Mark a media item as unwatched (clear watched state) for the authenticated
     * user (`POST /api/v1/media/{id}/unwatched`). The server returns a flat
     * `{ message }`. Non-2xx throw the shared {@link ApiError}.
     */
    markUnwatched(id: string): Promise<{ message: string }> {
        return this.post<{ message: string }>(`/api/v1/media/${encodeURIComponent(id)}/unwatched`);
    }

    /**
     * Delete a media item (`DELETE /api/v1/media/{id}`). Admin-only (server
     * enforces). Returns the deleted item id on success. Non-2xx throw the
     * shared {@link ApiError}.
     */
    deleteMediaItem(id: string): Promise<{ id: string }> {
        return this.delete<{ id: string }>(`/api/v1/media/${encodeURIComponent(id)}`);
    }

    /**
     * Set (or clear) the authenticated user's personal 1-10 rating for a media
     * item (`PUT /api/v1/media/{id}/rating`, body `{ rating }`). Pass `null` to
     * clear the rating. The server returns a flat `{ message }`. A non-integer /
     * out-of-range rating is a 400 → shared {@link ApiError}; 401/404 likewise.
     */
    setRating(id: string, rating: number | null): Promise<{ message: string }> {
        return this.put<{ message: string }>(
            `/api/v1/media/${encodeURIComponent(id)}/rating`,
            { rating },
        );
    }

    /**
     * Set the authenticated user's thumbs rating for a media item
     * (`PUT /api/v1/media/{id}/like`, body `{ level }`). `level` is the −2..2
     * thumbs axis (−2 strongly dislike … 0 not set … 2 love), a SEPARATE axis
     * from `rating`/`favorite`. The server returns a flat `{ message }`. A
     * non-integer / out-of-range level is a 400 → shared {@link ApiError};
     * 401/404 likewise.
     */
    setLikeLevel(id: string, level: number): Promise<{ message: string }> {
        return this.put<{ message: string }>(
            `/api/v1/media/${encodeURIComponent(id)}/like`,
            { level },
        );
    }

    /**
     * List the authenticated user's favorited media items, most-recently
     * favorited first (`GET /api/v1/users/me/favorites`). Each returned item is a
     * fully shaped {@link MediaItem} carrying its add-only `user_data` block.
     * `limit` (default server-side 50, clamped 1-100) and `offset` (default 0)
     * mirror the browse list endpoint. The `{ items, limit, offset }` envelope is
     * returned verbatim, with `items` defended to an array so a malformed payload
     * degrades to empty rather than throwing downstream.
     */
    async listFavorites(
        params: { limit?: number; offset?: number } = {},
        signal?: AbortSignal,
    ): Promise<FavoritesResult> {
        const query: Record<string, string> = {};
        if (params.limit !== undefined) query['limit'] = String(params.limit);
        if (params.offset !== undefined) query['offset'] = String(params.offset);
        const res = await this.get<Partial<FavoritesResult>>(
            '/api/v1/users/me/favorites',
            Object.keys(query).length ? query : undefined,
            signal,
        );
        return {
            items: Array.isArray(res.items) ? res.items : [],
            limit: typeof res.limit === 'number' ? res.limit : (params.limit ?? 50),
            offset: typeof res.offset === 'number' ? res.offset : (params.offset ?? 0),
        };
    }

    /**
     * List available poster candidates for one media item
     * (`GET /api/v1/media/{id}/posters`). Returns `{ candidates, current_poster_url }`
     * with `candidates` defended to an array so a malformed payload degrades
     * gracefully. A `422 metadata.tmdb_unconfigured` surfaces as an `ApiError`
     * the caller can detect with {@link isTmdbUnconfigured}.
     */
    async listPosters(id: string, signal?: AbortSignal): Promise<PosterCandidatesResponse> {
        const res = await this.get<Partial<PosterCandidatesResponse>>(
            `/api/v1/media/${encodeURIComponent(id)}/posters`,
            undefined,
            signal,
        );
        return {
            candidates: Array.isArray(res.candidates) ? res.candidates : [],
            current_poster_url:
                typeof res.current_poster_url === 'string' ? res.current_poster_url : null,
        };
    }

    /**
     * Set (or clear) the poster for one media item
     * (`PUT /api/v1/media/{id}/poster`, body `{ poster_url }`). Pass an empty
     * string to clear the poster. Returns the updated {@link MediaItem}. A
     * `422 metadata.tmdb_unconfigured` surfaces as an `ApiError` the caller
     * can detect with {@link isTmdbUnconfigured}.
     */
    setPoster(id: string, posterUrl: string): Promise<MediaItem> {
        return this.put<MediaItem>(`/api/v1/media/${encodeURIComponent(id)}/poster`, {
            poster_url: posterUrl,
        });
    }

    /**
     * Parse a non-ok response into the shared {@link ApiError} — the same
     * contract every other method on this class promises its callers (and what
     * `useAuthStore.parseErrorCode` reads via `body.code`). Used by the
     * hand-rolled multipart/DELETE paths that bypass {@link request}.
     */
    private async toApiError(response: Response): Promise<ApiError> {
        const contentType = response.headers.get('content-type') ?? '';
        let payload: unknown = null;
        try {
            payload = contentType.includes('application/json')
                ? await response.json()
                : await response.text();
        } catch {
            /* unreadable body — the status alone still identifies the failure */
        }
        return new ApiError(this.extractError(payload), response.status, payload);
    }

    /**
     * POST multipart/form-data to an endpoint. Used for file uploads like avatar
     * images. The Content-Type header is deliberately omitted so the browser
     * sets `Content-Type: multipart/form-data; boundary=...` with the correct
     * boundary automatically.
     */
    async postFormData(endpoint: string, body: FormData): Promise<unknown> {
        const headers: Record<string, string> = {
            ...defaultHeaders,
            ...this.instanceHeaders,
        };
        const token = this.tokens.getAccessToken();
        if (token) {
            headers['Authorization'] = `Bearer ${token}`;
        }
        // NOTE: NOT setting Content-Type — browser must set it with boundary for multipart/form-data
        const response = await this.doFetch(`${this.baseUrl}${endpoint}`, {
            method: 'POST',
            headers,
            credentials: 'same-origin',
            body,
        });
        if (!response.ok) throw await this.toApiError(response);
        return response.json();
    }

    /**
     * Upload the authenticated user's avatar image (`POST /api/v1/users/me/avatar`).
     * The server returns `{ avatar_url }`. Non-2xx throws the shared {@link ApiError}.
     */
    async uploadAvatar(file: File): Promise<{ avatar_url: string }> {
        const formData = new FormData();
        formData.append('avatar', file);
        return this.postFormData('/api/v1/users/me/avatar', formData) as Promise<{ avatar_url: string }>;
    }

    /**
     * Delete the authenticated user's avatar (`DELETE /api/v1/users/me/avatar`).
     * Non-2xx throws the shared {@link ApiError}.
     */
    async deleteAvatar(): Promise<void> {
        const headers: Record<string, string> = {
            ...defaultHeaders,
            ...this.instanceHeaders,
        };
        const token = this.tokens.getAccessToken();
        if (token) {
            headers['Authorization'] = `Bearer ${token}`;
        }
        const response = await this.doFetch(`${this.baseUrl}/api/v1/users/me/avatar`, {
            method: 'DELETE',
            headers,
            credentials: 'same-origin',
        });
        if (!response.ok) throw await this.toApiError(response);
    }

    isLoggedIn(): boolean {
        return this.tokens.getAccessToken() !== null;
    }

    async getCurrentUser(): Promise<AuthUser> {
        const raw = await this.get<{ user?: unknown }>('/api/v1/auth/me');
        const user = raw?.user;
        // Fail loud on a non-conforming 200 (a hub-relay proxy can answer `{}` —
        // previously this threw an opaque `TypeError: Cannot read 'is_admin' of
        // undefined`; ApiError keeps the store's parseErrorCode/logout path intact).
        if (!user || typeof user !== 'object') {
            throw new ApiError('Malformed /auth/me response: missing user object', 200, raw);
        }
        const fields = user as Record<string, unknown>;
        return { ...(user as AuthUser), is_admin: normalizeBool(fields['is_admin']) };
    }

    /**
     * Search for media items with markers near a specific playhead position (P3B-S8).
     *
     * Calls `GET /api/v1/media/search/by-marker?type={type}&around={around}&position={position}&limit={limit}`.</a>
     * Returns media items that have a marker of the specified type within $around seconds
     * of the given position, excluding already-watched items.
     *
     * @param type       Marker type: 'intro' | 'outro' | 'credits' | 'ad'
     * @param positionMs Current playhead position in milliseconds
     * @param aroundSec  Search window in seconds (default: 30)
     * @param limit      Maximum results (default: 20)
     * @param signal     Optional AbortSignal to cancel the request
     */
    async searchByMarker(
        type: 'intro' | 'outro' | 'credits' | 'ad',
        positionMs: number,
        aroundSec = 30,
        limit = 20,
        signal?: AbortSignal,
    ): Promise<{ items: MediaItem[]; marker_type: string; around: number; position: number }> {
        const params: Record<string, string> = {
            type,
            position: String(positionMs),
            around: String(aroundSec),
            limit: String(limit),
        };
        return this.get('/api/v1/media/search/by-marker', params, signal);
    }

    /**
     * Get trickplay (sprite preview) data for a media item.
     *
     * Calls `GET /api/v1/media/{id}/trickplay`. Returns the sprite sheet URL and
     * timeline mapping for thumbnail previews during scrubbing.
     *
     * @param id Media item ID
     * @param signal Optional AbortSignal to cancel the request
     */
    async getTrickplay(id: string, signal?: AbortSignal): Promise<{
        sprite_url: string | null;
        timeline: Array<{ seconds: number; frame: number }>;
    }> {
        return this.get(`/api/v1/media/${encodeURIComponent(id)}/trickplay`, undefined, signal);
    }

    /**
     * Create a new playlist (`POST /api/v1/playlists`, body
     * `{ name: string, library_id: string }`). Returns the created playlist
     * (`{ id, name }`) UNWRAPPED from the server's `{ collection: {...} }` 201
     * envelope. Non-2xx throws the shared {@link ApiError}; a malformed 2xx
     * throws an {@link ApiError} carrying status 200 — the same fail-loud
     * boundary {@link getCurrentUser} uses for a relay-answered `{}`.
     *
     * ⚠ 2026-10-02 contract fix: the server's create handler
     * (`CollectionController::create`) REQUIRES a non-empty `library_id` (it
     * 400s `library_id is required` without one) and NEVER reads `media_id` —
     * the old `{ name, media_id? }` body therefore 400ed for every role, and
     * even a fixed create adds no item: landing the media item is a SECOND leg
     * through {@link addToPlaylist} with the id returned here.
     */
    async createPlaylist(name: string, libraryId: string): Promise<{ id: string; name: string }> {
        const raw = await this.post<{ collection?: unknown }>('/api/v1/playlists', {
            name,
            library_id: libraryId,
        });
        const collection = raw?.collection;
        if (!collection || typeof collection !== 'object') {
            throw new ApiError(
                'Malformed /api/v1/playlists response: missing collection object',
                200,
                raw,
            );
        }
        const fields = collection as Record<string, unknown>;
        if (typeof fields['id'] !== 'string' || fields['id'] === '') {
            throw new ApiError(
                'Malformed /api/v1/playlists response: collection has no usable id',
                200,
                raw,
            );
        }
        return { id: fields['id'], name: typeof fields['name'] === 'string' ? fields['name'] : name };
    }

    /**
     * Add a media item to an existing playlist
     * (`POST /api/v1/collections/{id}/items/{mediaItemId}`).
     *
     * ⚠ S280: the server's playlist alias is `POST /api/v1/playlists`
     * (`CollectionController::create` — a playlist IS a collection), and
     * `createPlaylist` returns the collection id. Item-add is therefore the
     * collection route; the old `POST /api/v1/playlists/{playlistId}/items` was
     * never registered anywhere and 404ed against every real server (the S280
     * route gate caught it).
     */
     addToPlaylist(playlistId: string, mediaId: string): Promise<{ message: string }> {
         return this.post<{ message: string }>(
             `/api/v1/collections/${encodeURIComponent(playlistId)}/items/${encodeURIComponent(mediaId)}`,
         );
     }

    /**
     * R13-01 — the member-facing playlist surface (a playlist IS a collection;
     * server `CollectionController`, routes grouped under `[AuthMiddleware]`
     * since the Option-A ownership model). Visibility: `GET /api/v1/collections`
     * returns rows the actor owns plus legacy `created_by = NULL` rows; the
     * write handlers enforce `created_by === actor` (or admin) with a
     * byte-identical 404 on a miss.
     */
    getPlaylists(signal?: AbortSignal): Promise<PlaylistSummary[]> {
        return this.get<{ collections?: unknown }>('/api/v1/collections', undefined, signal).then(
            (raw) => (Array.isArray(raw?.collections) ? raw.collections : []).flatMap(parsePlaylistRow),
        );
    }

    /**
     * One playlist with its member rows
     * (`GET /api/v1/collections/{id}` → `{ collection, items, total }`).
     *
     * ⚠ Truth note: `items` are RAW hydrated DB rows (`SELECT *` + decoded
     * `metadata`), NOT response-shaped wire items — they carry no `poster_url`
     * or signed artwork (shaping happens only in `MediaItemShaper`). Consumers
     * that need poster/playback fields must resolve each id through
     * `GET /api/v1/media/{id}` (see `useMediaItemCache`), which is what
     * `PlaylistDetailPage` does.
     */
    getPlaylist(id: string, signal?: AbortSignal): Promise<PlaylistDetail> {
        return this.get<{ collection?: unknown; items?: unknown; total?: unknown }>(
            `/api/v1/collections/${encodeURIComponent(id)}`,
            undefined,
            signal,
        ).then((raw) => {
            const collection = parsePlaylistRow(raw?.collection)[0];
            if (!collection) {
                throw new ApiError(
                    'Malformed /api/v1/collections/{id} response: missing collection object',
                    200,
                    raw,
                );
            }
            const items = Array.isArray(raw?.items) ? raw.items.flatMap(parsePlaylistMediaRow) : [];
            return {
                collection,
                items,
                total: typeof raw?.total === 'number' ? raw.total : items.length,
            };
        });
    }

    /**
     * Remove one media item from a playlist the actor manages
     * (`DELETE /api/v1/collections/{id}/items/{mediaItemId}`).
     * Non-2xx throws the shared {@link ApiError}.
     */
    removeFromPlaylist(playlistId: string, mediaId: string): Promise<{ message: string }> {
        return this.delete<{ message: string }>(
            `/api/v1/collections/${encodeURIComponent(playlistId)}/items/${encodeURIComponent(mediaId)}`,
        );
    }

    /**
     * Delete an entire playlist the actor manages
     * (`DELETE /api/v1/collections/{id}`). R13-10: this is also the UNDO leg of
     * the two-leg create-and-add flow — when leg 2 (`addToPlaylist`) fails the
     * freshly created empty playlist is a stray artifact the picker offers to
     * clean up through this call. Non-2xx throws the shared {@link ApiError}.
     */
    deletePlaylist(id: string): Promise<{ message?: string }> {
        return this.delete<{ message?: string }>(`/api/v1/collections/${encodeURIComponent(id)}`);
    }

    /**
     * Get a download URL for a media item (`GET /api/v1/media/{id}/download`).
     * Returns `{ url: string }`. Non-2xx throws the shared {@link ApiError}.
     */
    getDownloadUrl(id: string): Promise<{ url: string }> {
        return this.get<{ url: string }>(`/api/v1/media/${encodeURIComponent(id)}/download`);
    }

    /**
     * Get the missing-episode report for a series media item
     * (`GET /api/v1/media/{id}/missing-episodes`).
     *
     * The server returns an ENVELOPE (snake_case, matching
     * `MediaItemController::getMissingEpisodes`), NOT a bare array:
     *   `{ total_expected, total_existing, missing_episodes: [{ episode_number }] }`.
     * `total_expected`/`total_existing` are omitted on the degraded branches
     * (item has no `metadata_json` or no positive `episode_count`), which still
     * return `{ missing_episodes: [] }` — hence both totals are optional and the
     * canonical count is always `missing_episodes.length`. Non-2xx throws the
     * shared {@link ApiError}.
     */
    getMissingEpisodes(id: string): Promise<{
        total_expected?: number;
        total_existing?: number;
        missing_episodes: Array<{ episode_number: number }>;
    }> {
        return this.get<{
            total_expected?: number;
            total_existing?: number;
            missing_episodes: Array<{ episode_number: number }>;
        }>(`/api/v1/media/${encodeURIComponent(id)}/missing-episodes`);
    }

    /**
     * Shuffle-play a media item (`POST /api/v1/shuffle`, body `{ media_id: string }`).
     * Returns a message. Non-2xx throws the shared {@link ApiError}.
     */
    shufflePlay(id: string): Promise<{ message: string }> {
        return this.post<{ message: string }>('/api/v1/shuffle', { media_id: id });
    }

    /**
     * Update metadata fields for a media item
     * (`PATCH /api/v1/media/{id}/metadata`, body is a partial media item).
     * Returns the updated media item. Non-2xx throws the shared {@link ApiError}.
     */
    updateMetadata(id: string, metadata: Record<string, unknown>): Promise<MediaItem> {
        return this.patch<MediaItem>(`/api/v1/media/${encodeURIComponent(id)}/metadata`, metadata);
    }

    /**
     * Search external subtitle providers for a media item (Wave 3 F3).
     *
     * Calls `GET /api/v1/media/{id}/subtitles/search?lang=en[,es]`. `langs` is a
     * list of BCP-47 codes joined into the `lang` query param; an empty list omits
     * it (server default). The server returns `{ candidates: [...] }` (empty when
     * the registry is empty or nothing matched) — each row is normalized to a typed
     * {@link SubtitleCandidate}. A malformed payload degrades to an empty array.
     * Non-2xx throws the shared {@link ApiError}.
     */
    async searchSubtitles(id: string, langs: string[], signal?: AbortSignal): Promise<SubtitleCandidate[]> {
        const lang = langs.filter((l) => l && l.trim() !== '').join(',');
        const params = lang !== '' ? { lang } : undefined;
        const res = await this.get<{ candidates?: unknown }>(
            `/api/v1/media/${encodeURIComponent(id)}/subtitles/search`,
            params,
            signal,
        );
        return Array.isArray(res.candidates) ? res.candidates.map(normalizeSubtitleCandidate) : [];
    }

    /**
     * Download a chosen subtitle candidate and attach it as an external track
     * (Wave 3 F3).
     *
     * Calls `POST /api/v1/media/{id}/subtitles/download` with the candidate's
     * `{ provider, downloadId, language, format?, releaseName?, hearingImpaired? }`.
     * Returns `{ track }` on `200` — the track surfaces through the existing player
     * `subtitle_tracks[]` contract on the item's next fetch. Non-2xx throws the
     * shared {@link ApiError}: `400` missing fields, `404` unknown item/provider,
     * `429` quota exhausted (body carries `downloadsRemaining`/`resetTimeUtc`),
     * `502` other provider failure. The caller inspects `ApiError.status`/`.body`.
     */
    downloadSubtitle(id: string, payload: SubtitleDownloadPayload): Promise<SubtitleDownloadResult> {
        return this.post<SubtitleDownloadResult>(
            `/api/v1/media/${encodeURIComponent(id)}/subtitles/download`,
            payload,
        );
    }

    /**
     * List ONE PAGE of music artists (`GET /api/v1/music/artists`), newest server
     * contract: `{ artists, total, limit, offset }` in snake_case, each row
     * normalized to a camelCase {@link MusicArtist} (the display `name` doubles as
     * the drill-down key). A malformed payload degrades to an empty page.
     *
     * ⚠ This is a PAGE, not the library. The endpoint clamps `?limit=` to
     * {@link MUSIC_PAGE_SIZE}, so a caller that ignores `total` shows the first 100
     * of 2,197 artists with no hint the rest exist — which is exactly the S110 bug
     * this signature exists to make impossible to write by accident.
     */
    async listArtists(
        params: MusicPageParams = {},
        signal?: AbortSignal,
    ): Promise<MusicArtistsResult> {
        const query = musicPageQuery(params);
        const res = await this.get<{ artists?: unknown; total?: unknown; limit?: unknown; offset?: unknown }>(
            '/api/v1/music/artists',
            Object.keys(query).length ? query : undefined,
            signal,
        );
        const raw = Array.isArray(res.artists) ? res.artists : [];
        return { artists: raw.map(normalizeMusicArtist), ...musicPageMeta(res, raw.length, params) };
    }

    /**
     * Fetch one artist by name (`GET /api/v1/music/artist?name=` — the server
     * keys artists by name, so `mbid` here is the artist name; S240 promoted this
     * to a query-param rail alongside the legacy `/music/artists/{mbid}` path).
     * Returns a normalized {@link MusicArtist}. A non-2xx (404 unknown artist)
     * throws the shared {@link ApiError}.
     */
    async getArtist(mbid: string, signal?: AbortSignal): Promise<MusicArtist> {
        const res = await this.get<{ artist?: unknown }>(
            `/api/v1/music/artist?name=${encodeURIComponent(mbid)}`,
            undefined,
            signal,
        );
        return normalizeMusicArtist(res.artist);
    }

    /**
     * List ONE PAGE of albums (`GET /api/v1/music/albums`), optionally filtered to
     * one artist SERVER-SIDE via `?artist=` (exact, case-insensitive, trimmed —
     * S99). Returns `{ albums, total, limit, offset, artist }`; `total` and the
     * `artist` echo both honour the filter. Each album carries its embedded
     * (normalized) track list, capped and flagged — see
     * {@link MusicAlbum.tracksTruncated}.
     *
     * ⚠ Do NOT filter by artist client-side over this page. `/albums` is ordered
     * globally by artist then title, so its first 100 rows span only ~23 of the
     * library's 2,197 artists: filtering page 1 in the browser made 77 of the 100
     * visible artists drill down to an EMPTY album list (the S110 bug). The
     * server-side filter is also ~140× cheaper (0.95 ms vs 134 ms, measured on
     * production) because it resolves through `music_albums.idx_artist`.
     */
    async listAlbums(
        params: MusicPageParams & { artist?: string } = {},
        signal?: AbortSignal,
    ): Promise<MusicAlbumsResult> {
        const query = musicPageQuery(params);
        if (params.artist !== undefined && params.artist !== '') {
            query['artist'] = params.artist;
        }
        const res = await this.get<{
            albums?: unknown; total?: unknown; limit?: unknown; offset?: unknown; artist?: unknown;
        }>(
            '/api/v1/music/albums',
            Object.keys(query).length ? query : undefined,
            signal,
        );
        const raw = Array.isArray(res.albums) ? res.albums : [];
        return {
            albums: raw.map(normalizeMusicAlbum),
            ...musicPageMeta(res, raw.length, params),
            artist: musicStr(res.artist),
        };
    }

    /**
     * Fetch one album by name (`GET /api/v1/music/album?name=` — the server keys
     * albums by name, so `mbid` here is the album name; S240 promoted this to a
     * query-param rail alongside the legacy `/music/albums/{mbid}` path), with the
     * whole track list embedded (the detail route exempts itself from the list
     * route's per-album track cap). Pass `artist` to disambiguate: 2,622 of
     * production's 5,091 album titles are shared by more than one artist, while
     * ZERO titles repeat WITHIN an artist — so `&artist=` makes this lookup exact
     * instead of "first by artist name, then lowest id". A non-2xx (404 unknown
     * album) throws {@link ApiError}.
     */
    async getAlbum(mbid: string, artist?: string, signal?: AbortSignal): Promise<MusicAlbum> {
        const disambiguate = artist !== undefined && artist !== '' ? `&artist=${encodeURIComponent(artist)}` : '';
        const res = await this.get<{ album?: unknown }>(
            `/api/v1/music/album?name=${encodeURIComponent(mbid)}${disambiguate}`,
            undefined,
            signal,
        );
        return normalizeMusicAlbum(res.album);
    }

    /**
     * List ONE PAGE of tracks (`GET /api/v1/music/tracks`) → `{ tracks, total,
     * limit, offset }`, each row a formatted {@link MusicTrack} carrying a signed
     * `stream_url`. A malformed payload degrades to an empty page.
     *
     * ⚠ There is deliberately no `album` argument. The endpoint has NO server-side
     * album filter, and filtering a 100-row page of 29,245 tracks in the browser
     * returns nothing for any album outside page 1 — the same defect as the album
     * drill-down. Use {@link getAlbum} (which embeds the album's whole track list)
     * to get one album's tracks.
     */
    async listTracks(
        params: MusicPageParams = {},
        signal?: AbortSignal,
    ): Promise<MusicTracksResult> {
        const query = musicPageQuery(params);
        const res = await this.get<{ tracks?: unknown; total?: unknown; limit?: unknown; offset?: unknown }>(
            '/api/v1/music/tracks',
            Object.keys(query).length ? query : undefined,
            signal,
        );
        const raw = Array.isArray(res.tracks) ? res.tracks : [];
        return { tracks: raw.map(normalizeMusicTrack), ...musicPageMeta(res, raw.length, params) };
    }

    /**
     * Fetch one track by id (`GET /api/v1/music/tracks/{id}` → `{ track }`).
     * Unlike the raw items embedded in an album, this formatted track carries a
     * server-minted signed `stream_url`, so `useMusicPlayer` calls it to resolve
     * a playable URL for tracks browsed via the album fast-path. Returns a
     * normalized {@link MusicTrack}; a non-2xx (404 unknown track) throws the
     * shared {@link ApiError}.
     */
    async getTrack(id: string, signal?: AbortSignal): Promise<MusicTrack> {
        const res = await this.get<{ track?: unknown }>(
            `/api/v1/music/tracks/${encodeURIComponent(id)}`,
            undefined,
            signal,
        );
        return normalizeMusicTrack(res.track);
    }

    logout(redirect = true): void {
        this.tokens.clear();
        if (redirect && typeof window !== 'undefined') {
            window.location.href = this.loginPath;
        }
    }
}

export const api = new ApiClient();
